#![deny(unsafe_code)]

mod app;
mod assets;
mod clap_app;
mod config;
mod directories;
mod input;

use std::io;
use std::io::Write;
use std::path::Path;
use std::process;

use crate::{
    app::App,
    config::{config_file, generate_config_file},
};

use directories::PROJECT_DIRS;

use bat::{
    config::Config,
    error::*,
    input::Input,
    style::{StyleComponent, StyleComponents},
    PagingMode,
};

fn run_cache_subcommand(
    app: &mut App,
    matches: &clap::ArgMatches,
    #[cfg(feature = "build-assets")] config_dir: &Path,
    default_cache_dir: &Path,
) -> Result<()> {
    app.run_cache_subcommand(
        matches,
        #[cfg(feature = "build-assets")]
        config_dir,
        default_cache_dir,
    )
}

pub fn get_languages(config: &Config, cache_dir: &Path) -> Result<String> {
    App::path_bootstrap().get_languages(config, cache_dir)
}

pub fn list_themes(cfg: &Config, config_dir: &Path, cache_dir: &Path) -> Result<()> {
    App::path_bootstrap().list_themes(cfg, config_dir, cache_dir)
}

fn run_controller(app: &App, inputs: Vec<Input>, config: &Config, cache_dir: &Path) -> Result<bool> {
    app.run_controller(inputs, config, cache_dir)
}

#[cfg(feature = "bugreport")]
fn invoke_bugreport(app: &App, cache_dir: &Path) {
    let pager = bat::config::get_pager_executable(
        app.matches.get_one::<String>("pager").map(|s| s.as_str()),
    )
    .unwrap_or_else(|| "less".to_owned());
    app.invoke_diagnostic_report(cache_dir, &pager);
}

/// Returns `Err(..)` upon fatal errors. Otherwise, returns `Ok(true)` on full success and
/// `Ok(false)` if any intermediate errors occurred (were printed).
fn run() -> Result<bool> {
    let mut app = App::new()?;
    let config_dir = PROJECT_DIRS.config_dir();
    let cache_dir = PROJECT_DIRS.cache_dir();

    if app.matches.get_flag("diagnostic") {
        #[cfg(feature = "bugreport")]
        invoke_bugreport(&app, cache_dir);
        #[cfg(not(feature = "bugreport"))]
        println!("bat has been built without the 'bugreport' feature. The '--diagnostic' option is not available.");
        return Ok(true);
    }

    let cache_subcommand = app
        .matches
        .subcommand()
        .map(|(name, matches)| (name.to_string(), matches.args_present(), matches.clone()));
    if let Some((name, args_present, cache_matches)) = cache_subcommand {
        if name == "cache" {
            // If there is a file named 'cache' in the current working directory,
            // arguments for subcommand 'cache' are not mandatory.
            // If there are non-zero arguments, execute the subcommand cache, else, open the file cache.
            if args_present {
                run_cache_subcommand(
                    &mut app,
                    &cache_matches,
                    #[cfg(feature = "build-assets")]
                    config_dir,
                    cache_dir,
                )?;
                return Ok(true);
            } else {
                let inputs = vec![Input::ordinary_file("cache")];
                let config = app.config(&inputs)?;
                return run_controller(&app, inputs, &config, cache_dir);
            }
        }
    }
    {
            let inputs = app.inputs()?;
            let config = app.config(&inputs)?;

            if app.matches.get_flag("list-languages") {
                let languages: String = app.get_languages(&config, cache_dir)?;
                let inputs: Vec<Input> = vec![Input::from_reader(Box::new(languages.as_bytes()))];
                let plain_config = Config {
                    style_components: StyleComponents::new(StyleComponent::Plain.components(false)),
                    paging_mode: PagingMode::QuitIfOneScreen,
                    ..Default::default()
                };
                run_controller(&app, inputs, &plain_config, cache_dir)
            } else if app.matches.get_flag("list-themes") {
                app.list_themes(&config, config_dir, cache_dir)?;
                Ok(true)
            } else if app.matches.get_flag("config-file") {
                println!("{}", config_file().to_string_lossy());
                Ok(true)
            } else if app.matches.get_flag("generate-config-file") {
                generate_config_file()?;
                Ok(true)
            } else if app.matches.get_flag("config-dir") {
                writeln!(io::stdout(), "{}", config_dir.to_string_lossy())?;
                Ok(true)
            } else if app.matches.get_flag("cache-dir") {
                writeln!(io::stdout(), "{}", cache_dir.to_string_lossy())?;
                Ok(true)
            } else if app.matches.get_flag("acknowledgements") {
                writeln!(io::stdout(), "{}", bat::assets::get_acknowledgements())?;
                Ok(true)
            } else {
                run_controller(&app, inputs, &config, cache_dir)
            }
    }
}

fn main() {
    let result = run();

    match result {
        Err(error) => {
            let stderr = std::io::stderr();
            default_error_handler(&error, &mut stderr.lock());
            process::exit(1);
        }
        Ok(false) => {
            process::exit(1);
        }
        Ok(true) => {
            process::exit(0);
        }
    }
}

