    term_width: usize,
    loop_through: bool,
    last_listing: String,
}

pub struct App {
    pub matches: ArgMatches,
    interactive_output: bool,
    config_source: ConfigSourceState,
    project_paths: ProjectPathState,
    asset_cache: AssetCacheState,
    paging_policy: PagingPolicyState,
    style_plan: StylePlanState,
    input_catalog: InputCatalogState,
    syntax_plan: SyntaxPlanState,
    theme_plan: ThemePlanState,
    terminal_plan: TerminalPlanState,
    listing_plan: ListingPlanState,
}

impl App {
    pub fn path_bootstrap() -> Self {
        App {
            matches: ArgMatches::default(),
            interactive_output: false,
            config_source: ConfigSourceState::default(),
            project_paths: ProjectPathState::default(),
            asset_cache: AssetCacheState::default(),
            paging_policy: PagingPolicyState::default(),
            style_plan: StylePlanState::default(),
            input_catalog: InputCatalogState::default(),
            syntax_plan: SyntaxPlanState::default(),
            theme_plan: ThemePlanState::default(),
            terminal_plan: TerminalPlanState::default(),
            listing_plan: ListingPlanState::default(),
        }
    }

    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = nu_ansi_term::enable_ansi_support();

        let interactive_output = std::io::stdout().is_terminal();
        let matches = Self::matches(interactive_output)?;
        let mut app = Self::path_bootstrap();
        app.matches = matches;
        app.interactive_output = interactive_output;
        app.hydrate_runtime_state();
        Ok(app)
    }

    fn matches(interactive_output: bool) -> Result<ArgMatches> {
        let mut assembler = Self::path_bootstrap();
        assembler.interactive_output = interactive_output;
        assembler.capture_project_paths();
        let args = assembler.assemble_cli_arguments()?;
        Ok(clap_app::build_app(interactive_output).get_matches_from(args))
    }

    fn hydrate_runtime_state(&mut self) {
        let matches = self.matches.clone();
        let interactive = self.interactive_output;
        self.capture_paging_policy(&matches, interactive);
        self.capture_style_plan(&matches, interactive);
        self.capture_input_catalog(&matches);
        self.capture_syntax_plan(&matches);
        self.capture_theme_plan(&matches);
        self.capture_terminal_plan(&matches);
        self.capture_listing_plan(&matches, interactive);
        self.capture_asset_cache_preferences(&matches);
        self.capture_project_paths();
    }

    pub fn config(&self, inputs: &[Input]) -> Result<Config> {
        let style_components = self.style_components()?;

        let paging_mode = match self.matches.get_one::<String>("paging").map(|s| s.as_str()) {
            Some("always") => PagingMode::Always,
            Some("never") => PagingMode::Never,
            Some("auto") | None => {
                // If we have -pp as an option when in auto mode, the pager should be disabled.
                let extra_plain = self.matches.get_count("plain") > 1;
                if extra_plain || self.matches.get_flag("no-paging") {
                    PagingMode::Never
                } else if inputs.iter().any(Input::is_stdin) {
                    // If we are reading from stdin, only enable paging if we write to an
                    // interactive terminal and if we do not *read* from an interactive
                    // terminal.
                    if self.interactive_output && !std::io::stdin().is_terminal() {
                        PagingMode::QuitIfOneScreen
                    } else {
                        PagingMode::Never
                    }
                } else if self.interactive_output {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            }
            _ => unreachable!("other values for --paging are not allowed"),
        };

        let syntax_mapping = self.build_syntax_mapping()?;
        let maybe_term_width = self.terminal_width_override();
        let wrapping_mode = self.wrapping_mode_value(&style_components, self.interactive_output);
        let tab_width = self.tab_width_value(&style_components, paging_mode);

        Ok(Config {
            true_color: is_truecolor_terminal(),
            language: self.language_override_value(),
            show_nonprintable: self.show_nonprintable_enabled(),
            nonprintable_notation: self.nonprintable_notation_setting(),
            binary: self.binary_behavior_setting(),
            wrapping_mode,
            colored_output: self.colored_output_enabled(self.interactive_output),
            paging_mode,
            term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
            loop_through: !(self.interactive_output
                || self.matches.get_one::<String>("color").map(|s| s.as_str()) == Some("always")
                || self
                    .matches
                    .get_one::<String>("decorations")
                    .map(|s| s.as_str())
                    == Some("always")
                || self.matches.get_flag("force-colorization")),
            tab_width,
            strip_ansi: self.strip_ansi_setting(),
            theme: self.theme_name(),
            visible_lines: self.visible_line_selection()?,
            style_components,
            syntax_mapping,
            pager: self.pager_command_from_policy(),
            use_italic_text: self.italic_text_enabled(),
            highlighted_lines: self.highlight_line_ranges()?,
            use_custom_assets: self.use_custom_assets_enabled(),
            #[cfg(feature = "lessopen")]
            use_lessopen: self.matches.get_flag("lessopen"),
            set_terminal_title: self.set_terminal_title_enabled(),
            squeeze_lines: self.squeeze_blank_limit(),
        })
    }
    pub fn assemble_cli_arguments(&mut self) -> Result<Vec<OsString>> {
        self.remember_config_source_flags();
        let args = if self.config_source.cache_subcommand {
            wild::args_os().collect::<Vec<_>>()
        } else if self.config_source.skip_config_file {
            let mut cli_args = wild::args_os();
            let mut args = self.collect_env_override_arguments();
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            self.config_source.last_option_kind = self.classify_config_option_token("--no-config");
            args
        } else {
            let mut cli_args = wild::args_os();
            let mut args = match self.load_opts_or_config_file() {
                Ok(v) => v,
